	effectiveDate.select(cb.max(ocpm1.get("effectiveDateStart")));
	Predicate a1 = cb.equal(c.get("exclusionId"),ocpm1.get("exclusionId"));
	Predicate a2 = cb.lessThanOrEqualTo(ocpm1.get("effectiveDateStart"), today);
